class Solution {
public:
    int nthUglyNumber(int n) {
        vector<int> u(1, 1);
        int i2 = 0, i3 = 0, i5 = 0;
        while ((int)u.size() < n) {
            int a = u[i2] * 2, b = u[i3] * 3, c = u[i5] * 5;
            int next = min({a, b, c});
            u.push_back(next);
            if (next == a) i2++;
            if (next == b) i3++;
            if (next == c) i5++;
        }
        return u[n - 1];
    }
};
